<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref } from 'vue';
import { Plus,Search,Truck,ArrowLeft } from 'lucide-vue-next';
import type {AccountInput,AccountView,Company,CompanyInput,LogisticsService,Province,Template,TemplateInput} from './types';
import { logisticsService } from './logisticsService';
import { currentUser } from '../../services/authSession';
import { message } from '../../components/feedback/message';
import AccessibleDialog from '../../components/AccessibleDialog.vue';
import CompanyForm from './components/CompanyForm.vue';
import AccountForm from './components/AccountForm.vue';
import FreightTemplateEditor from './components/FreightTemplateEditor.vue';
const props=withDefaults(defineProps<{service?:LogisticsService}>(),{service:()=>logisticsService});
const has=(permission:string)=>Boolean(currentUser.value?.permissions.includes(permission));
const canEdit=computed(()=>has('logistics:edit')),canConfigure=computed(()=>has('logistics:configure')),canTemplate=computed(()=>has('logistics:template'));
const rows=ref<Company[]>([]),total=ref(0),page=ref(1),keyword=ref(''),status=ref('');
const screen=ref(false),selected=ref<Company|null>(null),tab=ref<'company'|'account'|'templates'>('company');
const account=ref<AccountView|null>(null),history=ref<AccountView[]>([]),templates=ref<Template[]>([]),provinces=ref<Province[]>([]);
const templateDraft=ref<Template|null|undefined>(undefined),templatePage=ref(1),templateTotal=ref(0);
const loading=ref(false),sectionLoading=ref(false),busy=ref(false),error=ref(''),saveError=ref('');
const accountMetadataError=ref(''),companyNeedsRefresh=ref(false);
const statusChange=ref<{kind:'company'|'template';item:Company|Template}|null>(null);
let generation=0,sectionGeneration=0;
const pages=computed(()=>Math.max(1,Math.ceil(total.value/20)));
const errorText=(cause:unknown)=>cause instanceof Error?cause.message:'操作失败，请重试';
const originProvinceName=(value:string)=>provinces.value.find(province=>province.code===value || province.name===value)?.name??value;
async function load(){const token=++generation;loading.value=true;error.value='';try{const result=await props.service.listCompanies({page:page.value,size:20,keyword:keyword.value,status:status.value});if(token!==generation)return;rows.value=result.records;total.value=result.total;}catch(cause){if(token===generation)error.value=errorText(cause);}finally{if(token===generation)loading.value=false;}}
function open(company:Company|null){++sectionGeneration;selected.value=company;screen.value=true;sectionLoading.value=false;templatePage.value=1;tab.value='company';saveError.value='';error.value='';account.value=null;history.value=[];templates.value=[];templateDraft.value=undefined;accountMetadataError.value='';companyNeedsRefresh.value=false;}
function back(){++sectionGeneration;screen.value=false;selected.value=null;templateDraft.value=undefined;saveError.value='';error.value='';void load();}
async function switchTab(next:'company'|'account'|'templates'){
  if(busy.value || !selected.value || (next==='account'&&!canConfigure.value))return;
  ++sectionGeneration;sectionLoading.value=false;tab.value=next;templateDraft.value=undefined;saveError.value='';error.value='';
  if(next==='company')return;
  const token=++sectionGeneration,id=selected.value.id;sectionLoading.value=true;
  try{if(next==='account'){
    const [view,versions]=await Promise.all([props.service.getAccount(id),props.service.listAccounts(id)]);if(token!==sectionGeneration)return;account.value=view;history.value=versions.records;
  }else{const [result,catalog]=await Promise.all([props.service.listTemplates(id,{page:templatePage.value,size:20}),props.service.getProvinces()]);if(token!==sectionGeneration)return;templates.value=result.records;templateTotal.value=result.total;provinces.value=catalog;}
  }catch(cause){if(token===sectionGeneration){error.value=errorText(cause);message.error(error.value);}}
  finally{if(token===sectionGeneration)sectionLoading.value=false;}
}
async function saveCompany(input:CompanyInput){if(!canEdit.value||busy.value||companyNeedsRefresh.value)return;busy.value=true;saveError.value='';try{selected.value=await(selected.value?props.service.updateCompany(selected.value.id,input):props.service.createCompany(input));message.success('公司资料已保存');}catch(cause){saveError.value=errorText(cause);message.error(saveError.value);}finally{busy.value=false;}}
async function refreshAccountMetadata(){
  if(!selected.value)return;
  const id=selected.value.id;
  const [companyResult,historyResult]=await Promise.allSettled([props.service.getCompany(id),props.service.listAccounts(id)]);
  if(selected.value?.id!==id)return;
  const failures:string[]=[];
  if(companyResult.status==='fulfilled'){selected.value=companyResult.value;companyNeedsRefresh.value=false;}
  else{companyNeedsRefresh.value=true;failures.push(`公司资料刷新失败：${errorText(companyResult.reason)}`);}
  if(historyResult.status==='fulfilled')history.value=historyResult.value.records;
  else failures.push(`历史账号刷新失败：${errorText(historyResult.reason)}`);
  accountMetadataError.value=failures.length?`账号已保存，但${failures.join('；')}。请重试刷新。`:'';
  if(accountMetadataError.value)message.warning(accountMetadataError.value);
}
async function retryAccountMetadata(){if(busy.value)return;busy.value=true;try{await refreshAccountMetadata();}finally{busy.value=false;}}
async function saveAccount(input:AccountInput){if(!selected.value||!canConfigure.value||busy.value)return;busy.value=true;saveError.value='';try{account.value=await props.service.saveAccount(selected.value.id,input);companyNeedsRefresh.value=true;message.success('接口及寄件资料已保存');await refreshAccountMetadata();}catch(cause){saveError.value=errorText(cause);message.error(saveError.value);}finally{busy.value=false;}}
async function saveTemplate(input:TemplateInput){if(!selected.value||!canTemplate.value||busy.value)return;busy.value=true;saveError.value='';try{if(templateDraft.value)await props.service.updateTemplate(templateDraft.value.id,input);else await props.service.createTemplate(selected.value.id,input);templateDraft.value=undefined;message.success('运费模板已保存');busy.value=false;await switchTab('templates');}catch(cause){saveError.value=errorText(cause);message.error(saveError.value);}finally{busy.value=false;}}
async function confirmStatus(){const target=statusChange.value;if(!target||busy.value)return;if(target.kind==='company'?!canEdit.value:!canTemplate.value)return;busy.value=true;saveError.value='';try{const next=target.item.status==='enabled'?'disabled':'enabled';if(target.kind==='company'){await props.service.changeCompanyStatus(target.item.id,next,target.item.version);message.success('合作状态已更新');await load();}else{await props.service.changeTemplateStatus(target.item.id,next,target.item.version);message.success('模板状态已更新');busy.value=false;await switchTab('templates');}statusChange.value=null;}catch(cause){saveError.value=errorText(cause);message.error(saveError.value);}finally{busy.value=false;}}
onMounted(()=>{if(has('logistics:view'))void load();});
onBeforeUnmount(()=>{++generation;++sectionGeneration;});
</script>
<template>
  <section v-if="has('logistics:view')" data-testid="logistics-management" class="mx-auto w-full max-w-[1680px] space-y-5 pb-8">
    <p v-if="screen && accountMetadataError" role="status" class="rounded-lg bg-amber-50 p-3 text-sm text-amber-800">{{ accountMetadataError }} <button data-testid="account-metadata-retry" type="button" :disabled="busy" class="underline" @click="retryAccountMetadata">重试刷新</button></p>
    <header class="flex flex-wrap items-end justify-between gap-4"><div><button v-if="screen" data-testid="company-back" type="button" :disabled="busy" class="mb-3 flex items-center gap-1 text-sm text-indigo-600" @click="back"><ArrowLeft :size="16"/>返回物流公司列表</button><h1 class="text-2xl font-bold text-slate-800">{{ screen?(selected?.name || '新建物流公司'):'物流管理' }}</h1><p class="mt-2 text-sm text-slate-500">维护合作物流、接口账号与合同费率，为发货单提供可比较的运费依据。</p></div><button v-if="!screen && canEdit" data-testid="company-new" class="flex items-center gap-2 rounded-lg bg-indigo-500 px-5 py-3 text-sm font-semibold text-white" @click="open(null)"><Plus :size="17"/>新建物流公司</button></header>
    <div v-if="!screen" class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><form class="flex flex-wrap gap-3 p-5" @submit.prevent="page=1;load()"><label class="relative min-w-56 flex-1"><span class="sr-only">搜索物流公司</span><Search :size="16" class="absolute left-3 top-3 text-slate-400"/><input v-model="keyword" maxlength="100" placeholder="搜索公司名称 / 编码" class="control w-full pl-9"></label><select v-model="status" aria-label="合作状态筛选" class="control"><option value="">全部合作状态</option><option value="enabled">合作启用</option><option value="disabled">已停用</option></select><button class="rounded-lg bg-slate-800 px-5 py-2 text-sm text-white">查询</button></form><p v-if="error" role="alert" class="mx-5 mb-4 rounded-lg bg-rose-50 p-3 text-sm text-rose-700">{{ error }} <button class="underline" @click="load">重试</button></p><p v-if="loading" role="status" class="p-12 text-center text-slate-400">加载物流公司中…</p><div v-else-if="!rows.length && !error" class="p-16 text-center text-slate-400"><Truck :size="36" class="mx-auto mb-4"/><p>{{ keyword || status?'没有符合条件的物流公司':'暂无合作物流公司，请按合作合同录入公司及费率' }}</p></div><div v-else-if="!error" class="overflow-x-auto"><table class="w-full min-w-[900px] whitespace-nowrap text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th>物流公司</th><th>接口类型</th><th>联系人</th><th>合作状态</th><th>排序</th><th>更新时间</th><th class="text-right">操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" class="border-t border-slate-100"><td><strong class="text-slate-800">{{ row.name }}</strong><p class="mt-1 text-xs text-slate-400">{{ row.code }}</p></td><td>{{ row.provider==='ANE'?'安能 ANE':'未接入 · 线下下单' }}</td><td>{{ row.contactName || '—' }}<p class="mt-1 text-xs text-slate-400">{{ row.contactPhone }}</p></td><td><span class="rounded-full px-3 py-1 text-xs" :class="row.status==='enabled'?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-500'">{{ row.status==='enabled'?'合作启用':'已停用' }}</span></td><td>{{ row.sortOrder }}</td><td class="text-xs text-slate-400">{{ row.updatedAt?.replace('T',' ').slice(0,16) }}</td><td class="space-x-4 text-right text-indigo-600"><button :data-testid="`company-configure-${row.id}`" @click="open(row)">配置详情</button><button v-if="canEdit" :data-testid="`company-status-${row.id}`" :disabled="busy" @click="saveError='';statusChange={kind:'company',item:row}">{{ row.status==='enabled'?'停用':'启用' }}</button></td></tr></tbody></table></div><footer class="flex items-center justify-between border-t p-5 text-sm text-slate-500"><span>共 {{ total }} 家合作物流</span><div class="flex items-center gap-4"><button :disabled="loading || page<=1" @click="page--;load()">上一页</button><span>{{ page }} / {{ pages }}</span><button :disabled="loading || page>=pages" @click="page++;load()">下一页</button></div></footer></div>
    <div v-else class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><nav v-if="selected" class="flex gap-7 border-b px-6" aria-label="物流公司配置"><button type="button" :disabled="busy" class="tab" :class="{'active':tab==='company'}" @click="switchTab('company')">公司资料</button><button v-if="canConfigure" data-testid="account-tab" type="button" :disabled="busy" class="tab" :class="{'active':tab==='account'}" @click="switchTab('account')">接口及寄件资料</button><button type="button" :disabled="busy" class="tab" :class="{'active':tab==='templates'}" @click="switchTab('templates')">合作运费模板</button></nav><div class="p-6"><p v-if="error" role="alert" class="mb-5 rounded bg-rose-50 p-3 text-sm text-rose-700">{{ error }} <button type="button" class="underline" @click="switchTab(tab)">重试</button></p><p v-if="sectionLoading" role="status" class="p-8 text-center text-slate-400">加载配置中…</p><template v-else-if="tab==='company'"><CompanyForm v-if="canEdit" :key="`${selected?.id ?? 'new'}-${selected?.version??0}`" :company="selected" :busy="busy || companyNeedsRefresh" :error="saveError" @save="saveCompany" @cancel="back"/><dl v-else class="grid gap-4 text-sm md:grid-cols-2"><div><dt class="text-slate-400">公司名称</dt><dd class="mt-1">{{ selected?.name }}</dd></div><div><dt class="text-slate-400">内部编码</dt><dd class="mt-1">{{ selected?.code }}</dd></div><div><dt class="text-slate-400">联系人 / 电话</dt><dd class="mt-1">{{ selected?.contactName || '—' }} {{ selected?.contactPhone }}</dd></div><div><dt class="text-slate-400">备注</dt><dd class="mt-1">{{ selected?.remark || '—' }}</dd></div></dl></template><template v-else-if="tab==='account' && canConfigure && !error"><AccountForm :key="`${account?.id??0}-${account?.version??0}`" :account="account" :busy="busy" :error="saveError" @save="saveAccount"/><details v-if="history.length" class="mt-6 border-t pt-4 text-sm"><summary class="cursor-pointer text-slate-600">历史账号元数据（{{ history.length }}）</summary><table class="mt-3 w-full text-left text-xs"><thead><tr><th>账号编码</th><th>客户编码</th><th>环境</th><th>版本</th><th>配置状态</th></tr></thead><tbody><tr v-for="item in history" :key="`${item.id}-${item.version}`" class="border-t"><td>{{ item.code }}</td><td>{{ item.customerCode }}</td><td>{{ item.environment }}</td><td>{{ item.version }}</td><td>{{ item.ready?'完整':item.message }}</td></tr></tbody></table></details></template><template v-else-if="tab==='templates' && !error"><FreightTemplateEditor v-if="templateDraft!==undefined && canTemplate" :key="templateDraft?.id??'new'" :template="templateDraft" :sender="account?.sender" :provinces="provinces" :busy="busy" :error="saveError" @save="saveTemplate" @cancel="templateDraft=undefined;saveError=''"/><template v-else><header class="mb-5 flex items-start justify-between gap-4"><div><h3 class="font-semibold text-slate-800">合作运费模板</h3><p class="mt-1 text-xs text-slate-500">按公司、产品和发货地维护合同；启用后参与新报价，历史报价保持原版本。</p></div><button v-if="canTemplate" data-testid="template-new" type="button" class="rounded bg-indigo-500 px-4 py-2 text-sm text-white" @click="templateDraft=null;saveError=''">新建运费模板</button></header><p v-if="!templates.length" class="rounded border border-dashed p-12 text-center text-sm text-slate-400">暂无运费模板。未配置价格不会显示为零元。</p><div v-else class="overflow-x-auto"><table class="w-full min-w-[760px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th>模板名称 / 产品</th><th>发货地</th><th>计价 / 地区</th><th>状态 / 版本</th><th class="text-right">操作</th></tr></thead><tbody><tr v-for="item in templates" :key="item.id" class="border-t"><td><strong>{{ item.name }}</strong><p class="mt-1 text-xs text-slate-500">{{ item.productName }} · {{ item.productCode }}</p></td><td>{{ originProvinceName(item.originProvince) }} {{ item.originCity }} {{ item.originCounty }}</td><td>{{ item.rules.mode==='piece'?'按件':'按重' }}{{ item.rules.volumetric?' / 体积重':'' }}<p class="mt-1 text-xs text-slate-500">{{ item.rules.defaultBands.length?'有默认费率':'无默认费率' }} · {{ item.rules.regionGroups.length }} 地区组</p></td><td>{{ item.status==='enabled'?'启用':'草稿 / 停用' }} · v{{ item.version }}</td><td class="space-x-4 text-right text-indigo-600"><template v-if="canTemplate"><button @click="templateDraft=item;saveError=''">编辑</button><button @click="saveError='';statusChange={kind:'template',item}">{{ item.status==='enabled'?'停用':'启用' }}</button></template><span v-else class="text-slate-400">只读</span></td></tr></tbody></table></div><footer v-if="templateTotal>20" class="mt-4 flex items-center justify-end gap-4 text-sm text-slate-500"><button :disabled="templatePage<=1" @click="templatePage--;switchTab('templates')">上一页</button><span>{{ templatePage }} / {{ Math.ceil(templateTotal/20) }}</span><button :disabled="templatePage>=Math.ceil(templateTotal/20)" @click="templatePage++;switchTab('templates')">下一页</button></footer></template></template></div></div>
    <AccessibleDialog v-if="statusChange" :open="true" :title="statusChange.item.status==='enabled'?'确认停用':'确认启用'" description="修改状态不会触发真实物流请求。" test-id="logistics-status-dialog" body-test-id="logistics-status-body" footer-test-id="logistics-status-footer" close-test-id="logistics-status-close" panel-class="w-[min(520px,calc(100vw-48px))]" @cancel="!busy && (statusChange=null)"><p class="text-sm text-slate-600">{{ statusChange.item.status==='enabled'?'停用':'启用' }}“{{ statusChange.item.name }}”？{{ statusChange.item.status==='enabled'?'停用后不再参与新报价，历史记录保留。':'模板启用前将校验完整费率。' }}</p><p v-if="saveError" role="alert" class="mt-4 text-sm text-rose-600">{{ saveError }}</p><template #footer><div class="flex justify-end gap-3"><button type="button" :disabled="busy" class="rounded border px-4 py-2 text-sm" @click="statusChange=null">取消</button><button data-testid="status-confirm" type="button" :disabled="busy" class="rounded bg-indigo-500 px-4 py-2 text-sm text-white" @click="confirmStatus">{{ busy?'处理中…':'确认' }}</button></div></template></AccessibleDialog>
  </section><p v-else role="alert" class="p-8 text-slate-500">没有物流管理查看权限。</p>
</template>
<style scoped>.control{@apply rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm outline-none focus:border-indigo-400;}.tab{@apply border-b-2 border-transparent py-4 text-sm font-semibold text-slate-500;}.tab.active{@apply border-indigo-500 text-indigo-600;}th,td{@apply px-4 py-4;}button:disabled{@apply cursor-not-allowed opacity-40;}</style>
